<script setup lang="ts">
import { ref } from 'vue'
import PageHeader from '../components/layout/PageHeader.vue'
import Toast from '../components/common/Toast.vue'
import { useSimpleFlowStore } from '../stores/simpleFlowStore'
import { useTaskStore } from '../stores/taskStore'
import { functions } from '../services/profile'
import { loadMock } from '../api/mockApi'
const flow=useSimpleFlowStore(),task=useTaskStore(),error=ref(''),busy=ref(false),dragging=ref(false)
async function read(files:FileList|null){const file=files?.[0];if(!file)return;busy.value=true;error.value='';try{if(!/\.(geojson|json)$/i.test(file.name))throw new Error('当前支持 GeoJSON / JSON；SHP、GPKG 请先另存为 WGS84 GeoJSON');if(file.size>10*1024*1024)throw new Error('文件超过10MB，请分批处理');flow.setSource(await file.text(),file.name)}catch(e){error.value=String(e)}finally{busy.value=false}}
async function demo(){try{const data=await loadMock(task.activeId==='village-boundary'?'village-demo.geojson':'flow-demo.geojson');flow.setSource(JSON.stringify(data),task.activeId==='village-boundary'?'两村边界_演示矢量.geojson':'演示村_原始矢量.geojson',true);error.value=''}catch(e){error.value=String(e)}}
</script>
<template><PageHeader title="上传原始矢量" description="选择文件和模板，下一步设置字段映射。"/><div class="two-column"><section class="panel"><h2>选择文件</h2><label class="dropzone" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave="dragging=false" @drop.prevent="dragging=false;read($event.dataTransfer?.files||null)"><span class="upload-symbol">↥</span><strong>{{busy?'正在读取…':'拖入 GeoJSON，或点击选择文件'}}</strong><small>本地读取 · WGS84 经纬度 · 最多250个要素 / 10MB</small><input type="file" accept=".geojson,.json" :disabled="busy" @change="read(($event.target as HTMLInputElement).files)"></label><button class="secondary full-width" :disabled="busy" @click="demo">{{task.activeId==='village-boundary'?'使用两村边界演示矢量':'使用演示矢量'}}</button><Toast :message="error"/><p class="hint">仅在浏览器处理。更换文件会重置映射和成果；SHP / GPKG / CAD 请先转为 GeoJSON。</p></section><section class="panel"><h2>选择导出模板</h2><div class="template-choices"><label v-for="(f,i) in functions" :key="f.id" :class="{chosen:task.activeId===f.id}"><input v-model="task.activeId" type="radio" name="template" :value="f.id"><span><strong>{{f.name}}</strong><small>{{[34,12,8,22][i]}} 个模板字段 · {{f.id==='village-boundary'?'每个村单独一表':'未映射字段统一留空'}}</small></span></label></div><div v-if="flow.source" class="notice success-notice">已读取 {{flow.fileName}}<br>{{flow.source.features.length}} 个要素 · {{flow.fields.length}} 个原始字段 · {{flow.demo?'演示数据':'本地文件'}}</div><RouterLink class="button full-width" :class="{disabled:!flow.source||busy}" to="/mapping">下一步：字段映射与拓扑检查 →</RouterLink></section></div><section v-if="flow.source" class="panel"><div class="section-heading"><h2>原始字段</h2></div><div class="raw-tags"><span v-for="f in flow.fields" :key="f">{{f}}</span></div></section></template>
